// SwatchRenderer.swift
//
// Draws a MaterialX shader (generated by MXKit) on a sphere, offscreen, with
// our own small Metal pipeline. This is the PreviewService of PLAN.md §5:
// spike M0c (docs/spikes/M0c-msl-swatch.md) made it, M3c put it on the
// canvas's nodes.
//
// How a generated shader gets its inputs. MaterialX's MSL puts parameters in
// structs passed in buffers ("u_pub" for the node inputs, "u_prv" for
// renderer-provided values such as matrices, "u_lightData" for lights), and
// environment maps and file images in textures. Which buffer index each one
// gets differs from shader to shader. Rather than parse the source, we ask
// Metal: building the pipeline with *reflection* returns every buffer's
// index, size and struct layout (member names and byte offsets). We then
// fill each member by name. MaterialX's own Metal renderer
// (MaterialXRenderMsl, not shipped in SwiftUsd) works the same way.
//
// What M3c added, so swatches can be redrawn after every edit and agree
// with the viewport:
//
//  - A pipeline cache, keyed by a digest of the source. A value edit
//    changes uniforms, not the source, so the swatches it affects are
//    drawn again in about a millisecond each instead of compiled again
//    (170–450 ms). Compiling can also happen ahead, on any thread, and in
//    parallel (``SwatchPipeline/compile(_:device:)``).
//  - The viewport's light (SwatchEnvironment) and camera angle, and its
//    OCIO view transform: the linear render goes through DisplayPass, and
//    the image is tagged with the display's colour space.
//  - File textures, loaded once per path; missing ones stay mid-grey.
//
// Introduces (SWIFT): `throws` initializers that do real work, `as?`
// conditional casts, `switch` over a C-style enum with `default`,
// `UnsafeMutableRawPointer` and `storeBytes`, `Dictionary` lookups,
// `simd_float4x4` matrices (M0c); CryptoKit's SHA256, Objective-C
// completion handlers called with `await`, an option dictionary
// (`MTKTextureLoader`) (M3c).

import ColorKit
import CoreGraphics
import CryptoKit
import Foundation
import Metal
import MetalKit
import MXKit
import simd

/// A compiled swatch shader: its pipeline and the reflection that says
/// where its inputs go.
///
/// SWIFT: `@unchecked Sendable` promises the compiler that instances may be
/// shared between threads, which it can't check itself here:
/// MTLRenderPipelineReflection is an Objective-C class not marked Sendable.
/// The promise holds because both properties are `let`s that nothing
/// changes after compilation; Metal's pipeline states are thread-safe, and
/// the reflection is only read.
public final class SwatchPipeline: @unchecked Sendable {
    let state: any MTLRenderPipelineState
    let reflection: MTLRenderPipelineReflection

    init(state: any MTLRenderPipelineState, reflection: MTLRenderPipelineReflection) {
        self.state = state
        self.reflection = reflection
    }

    /// Compiles `shader`'s two stages and builds its pipeline, with
    /// reflection. Can run on any thread, several at once: Metal compiles
    /// in its own service process, which handles concurrent requests.
    ///
    /// SWIFT: `async`: the Metal compiler's completion-handler API, called
    /// with `await`, suspends this task instead of blocking its thread.
    /// The thread can run other tasks meanwhile.
    public static func compile(_ shader: MXGeneratedShader, device: any MTLDevice) async throws -> SwatchPipeline {
        let vertexLibrary: any MTLLibrary
        let fragmentLibrary: any MTLLibrary
        // SWIFT: `do`/`catch` to translate Metal's compiler error into ours,
        // keeping the compiler's message.
        do {
            vertexLibrary = try await device.makeLibrary(source: shader.vertexSource, options: nil)
            fragmentLibrary = try await device.makeLibrary(source: shader.pixelSource, options: nil)
        } catch {
            throw PreviewError.compileFailed(compilerErrors(in: error.localizedDescription))
        }
        let descriptor: MTLRenderPipelineDescriptor = try makeDescriptor(vertex: vertexLibrary,
                                                                         fragment: fragmentLibrary)
        // `.bindingInfo` asks for the list of bindings, `.bufferTypeInfo`
        // for the struct layout inside each buffer.
        let (state, reflection) = try await device.makeRenderPipelineState(
            descriptor: descriptor, options: [.bindingInfo, .bufferTypeInfo])
        guard let reflection else {
            throw PreviewError.metal("No pipeline reflection")
        }
        return SwatchPipeline(state: state, reflection: reflection)
    }

    /// The same as ``compile(_:device:)``, blocking the calling thread
    /// while Metal compiles.
    ///
    /// SWIFT: A synchronous function can't `await`, so this repeats the
    /// steps with Metal's blocking calls rather than wait for the async
    /// version (which would need a semaphore, and could deadlock).
    static func compileNow(_ shader: MXGeneratedShader, device: any MTLDevice) throws -> SwatchPipeline {
        let vertexLibrary: any MTLLibrary
        let fragmentLibrary: any MTLLibrary
        do {
            vertexLibrary = try device.makeLibrary(source: shader.vertexSource, options: nil)
            fragmentLibrary = try device.makeLibrary(source: shader.pixelSource, options: nil)
        } catch {
            throw PreviewError.compileFailed(compilerErrors(in: error.localizedDescription))
        }
        let descriptor: MTLRenderPipelineDescriptor = try makeDescriptor(vertex: vertexLibrary,
                                                                         fragment: fragmentLibrary)
        let (state, reflection) = try device.makeRenderPipelineState(
            descriptor: descriptor, options: [.bindingInfo, .bufferTypeInfo])
        guard let reflection else {
            throw PreviewError.metal("No pipeline reflection")
        }
        return SwatchPipeline(state: state, reflection: reflection)
    }

    /// The pipeline's description: the generated entry points, the
    /// sphere's vertex layout, and the swatch's targets.
    private static func makeDescriptor(vertex: any MTLLibrary,
                                       fragment: any MTLLibrary) throws -> MTLRenderPipelineDescriptor {
        guard let vertexFunction = vertex.makeFunction(name: "VertexMain"),
              let fragmentFunction = fragment.makeFunction(name: "FragmentMain")
        else {
            throw PreviewError.compileFailed("VertexMain or FragmentMain missing")
        }
        let descriptor = MTLRenderPipelineDescriptor()
        descriptor.vertexFunction = vertexFunction
        descriptor.fragmentFunction = fragmentFunction
        descriptor.vertexDescriptor = try SwatchGeometry.vertexDescriptor(for: vertexFunction)
        descriptor.colorAttachments[0].pixelFormat = SwatchRenderer.colorFormat
        descriptor.depthAttachmentPixelFormat = .depth32Float
        descriptor.rasterSampleCount = SwatchRenderer.sampleCount
        return descriptor
    }

    /// The compiler's error lines, without its warnings (MaterialX's MSL
    /// always earns a few, starting with a redefined `__METAL__`).
    static func compilerErrors(in message: String) -> String {
        let errors: [Substring] = message.split(separator: "\n").filter { $0.contains("error:") }
        return errors.isEmpty ? message : errors.joined(separator: "\n")
    }
}

/// Renders swatches: one MaterialX shader on a lit sphere.
///
/// Create one per device and reuse it; it holds the sphere, the
/// environment textures, the compiled pipelines and the loaded file
/// textures. Not thread-safe: use it from one thread, or from inside one
/// actor (SwatchService).
public final class SwatchRenderer {
    /// The GPU.
    public let device: any MTLDevice
    /// The queue all swatch rendering runs on.
    public let commandQueue: any MTLCommandQueue

    private let geometry: SwatchGeometry
    /// The environment, by the colour space of its values (M7e): the
    /// image's own (lin_rec709) first, the others made when a shader
    /// computing in them is first drawn.
    private var environments: [String: SwatchEnvironment]
    /// The image the swatches are lit by.
    public private(set) var environmentURL: URL
    /// Samples environment maps: linear filtering between pixels and mips,
    /// wrapping horizontally (longitude), clamped vertically (latitude).
    private let environmentSampler: any MTLSamplerState
    /// Samples file images: linear and mipmapped, repeating both ways, so
    /// `tiledimage` tiles.
    private let imageSampler: any MTLSamplerState
    /// Depth testing: nearer fragments win.
    private let depthState: any MTLDepthStencilState
    /// For file images that can't be loaded: one mid-grey pixel, so
    /// shaders still compile and run.
    private let placeholderTexture: any MTLTexture
    private let textureLoader: MTKTextureLoader

    /// Compiled pipelines by shader digest (see ``key(for:)``).
    private var pipelines: [String: SwatchPipeline] = [:]
    /// File textures by path; the placeholder for those that failed.
    private var images: [String: any MTLTexture] = [:]

    /// The view transform swatches are shown with, or nil for plain sRGB.
    public private(set) var viewTransform: ViewTransform?
    /// Turn the linear render into the display's encoding, one for each
    /// colour space renders are in (M7e), made when first needed.
    private var displayPasses: [String: DisplayPass] = [:]
    /// The same for data swatches (M3d): the display's Raw view, which
    /// shows values unconverted (see ViewTransform.raw).
    private var dataPass: DisplayPass

    /// The colour format swatches are rendered in: linear, half float.
    static let colorFormat: MTLPixelFormat = .rgba16Float

    /// Samples per pixel (multisample anti-aliasing). Swatches are small, so
    /// jagged edges show; 4 is supported by every Mac GPU.
    static let sampleCount: Int = 4

    /// How many compiled pipelines to keep. A big graph has a few hundred
    /// distinct shaders; each pipeline is some hundreds of kilobytes.
    static let pipelineLimit: Int = 400

    /// Sets up the renderer on the system's default GPU, lit by the image
    /// at `environmentURL` (nil: OpenUSD's StinsonBeach.hdr), and shown
    /// with `viewTransform`.
    public init(environment environmentURL: URL? = StudioEnvironment.fileURL,
                viewTransform: ViewTransform? = .standard) throws {
        // SWIFT: `guard let ... else { throw }` is the usual way to turn a
        // nil from an Objective-C API into a Swift error.
        guard let device = MTLCreateSystemDefaultDevice(),
              let queue = device.makeCommandQueue()
        else {
            throw PreviewError.metal("No Metal device")
        }
        self.device = device
        self.commandQueue = queue
        self.geometry = try SwatchGeometry(device: device)
        let imageURL: URL = try environmentURL ?? SwatchEnvironment.defaultImageURL()
        let environment = try SwatchEnvironment(imageURL: imageURL, queue: queue)
        self.environments = [environment.colorSpace: environment]
        self.environmentURL = imageURL
        self.textureLoader = MTKTextureLoader(device: device)
        self.viewTransform = viewTransform
        self.displayPasses = [ViewTransform.sceneSpace: try Self.makeDisplayPass(for: viewTransform, device: device)]
        self.dataPass = try Self.makeDisplayPass(for: viewTransform?.raw ?? viewTransform, device: device)

        let samplerDescriptor = MTLSamplerDescriptor()
        samplerDescriptor.minFilter = .linear
        samplerDescriptor.magFilter = .linear
        samplerDescriptor.mipFilter = .linear
        samplerDescriptor.sAddressMode = .repeat
        samplerDescriptor.tAddressMode = .clampToEdge
        guard let sampler = device.makeSamplerState(descriptor: samplerDescriptor) else {
            throw PreviewError.metal("Could not create a sampler")
        }
        self.environmentSampler = sampler
        samplerDescriptor.tAddressMode = .repeat
        guard let imageSampler = device.makeSamplerState(descriptor: samplerDescriptor) else {
            throw PreviewError.metal("Could not create a sampler")
        }
        self.imageSampler = imageSampler

        // SWIFT: This used to be a `static let` holding the descriptor, and
        // Swift 6 rejected it: a static property is a global any thread can
        // reach, and MTLDepthStencilDescriptor is a mutable, non-Sendable
        // class, so sharing it could be a data race. Creating the state here,
        // once per renderer, avoids sharing anything.
        let depthDescriptor = MTLDepthStencilDescriptor()
        depthDescriptor.depthCompareFunction = .less
        depthDescriptor.isDepthWriteEnabled = true
        guard let depthState = device.makeDepthStencilState(descriptor: depthDescriptor) else {
            throw PreviewError.metal("Could not create the depth state")
        }
        self.depthState = depthState

        let placeholderDescriptor = MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat: .rgba8Unorm, width: 1, height: 1, mipmapped: false)
        guard let placeholder = device.makeTexture(descriptor: placeholderDescriptor) else {
            throw PreviewError.metal("Could not create a placeholder texture")
        }
        let grey: [UInt8] = [128, 128, 128, 255]
        placeholder.replace(region: MTLRegionMake2D(0, 0, 1, 1), mipmapLevel: 0, withBytes: grey, bytesPerRow: 4)
        self.placeholderTexture = placeholder
    }

    // MARK: Settings

    /// Lights the swatches with the image at `url` (nil: StinsonBeach.hdr).
    /// Does nothing if that is the image already in use.
    public func setEnvironment(_ url: URL?) throws {
        let imageURL: URL = try url ?? SwatchEnvironment.defaultImageURL()
        guard imageURL != environmentURL else {
            return
        }
        let environment = try SwatchEnvironment(imageURL: imageURL, queue: commandQueue)
        environments = [environment.colorSpace: environment]
        environmentURL = imageURL
    }

    /// The environment with its values in `space`, made the first time.
    private func environment(in space: String) throws -> SwatchEnvironment {
        if let environment = environments[space] {
            return environment
        }
        let environment = try SwatchEnvironment(imageURL: environmentURL, colorSpace: space, queue: commandQueue)
        environments[space] = environment
        return environment
    }

    /// Shows the swatches with `transform` (nil: plain sRGB).
    public func setViewTransform(_ transform: ViewTransform?) throws {
        guard transform != viewTransform else {
            return
        }
        displayPasses = [ViewTransform.sceneSpace: try Self.makeDisplayPass(for: transform, device: device)]
        dataPass = try Self.makeDisplayPass(for: transform?.raw ?? transform, device: device)
        viewTransform = transform
    }

    /// The pass for `transform`, writing 8-bit display values: the
    /// transform's output is already encoded for the display, so 8 bits
    /// lose nothing a screen shows. From renders in `space`; the Raw view
    /// of data swatches converts nothing, whatever the space.
    private static func makeDisplayPass(for transform: ViewTransform?, from space: String = ViewTransform.sceneSpace,
                                        device: any MTLDevice) throws -> DisplayPass {
        try DisplayPass(device: device, pixelFormat: .rgba8Unorm, encoding: .linearPremultiplied,
                        transform: transform?.shader(from: space))
    }

    /// The display pass for renders in `space`, made the first time.
    private func displayPass(from space: String) throws -> DisplayPass {
        if let pass = displayPasses[space] {
            return pass
        }
        let pass: DisplayPass = try Self.makeDisplayPass(for: viewTransform, from: space, device: device)
        displayPasses[space] = pass
        return pass
    }

    // MARK: Pipelines

    /// The cache key for `shader`: a SHA-256 digest of its two sources, so
    /// the cache doesn't keep every source (about 100 kB each for a surface
    /// shader).
    ///
    /// SWIFT: CryptoKit is Apple's hashing and encryption framework.
    /// `SHA256.hash(data:)` returns a digest; `.map { String(format:) }`
    /// turns its bytes into hex.
    public static func key(for shader: MXGeneratedShader) -> String {
        var hasher = SHA256()
        hasher.update(data: Data(shader.vertexSource.utf8))
        hasher.update(data: Data(shader.pixelSource.utf8))
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }

    /// True if `shader`'s pipeline is compiled and cached.
    public func hasPipeline(for shader: MXGeneratedShader) -> Bool {
        pipelines[Self.key(for: shader)] != nil
    }

    /// Caches a pipeline compiled elsewhere (by ``SwatchPipeline/compile(_:device:)``).
    public func add(_ pipeline: SwatchPipeline, for shader: MXGeneratedShader) {
        if pipelines.count >= Self.pipelineLimit {
            // Simple, and rare: start again rather than track use.
            pipelines.removeAll()
        }
        pipelines[Self.key(for: shader)] = pipeline
    }

    /// `shader`'s pipeline, from the cache or compiled now (blocking the
    /// calling thread while Metal compiles).
    private func pipeline(for shader: MXGeneratedShader) throws -> SwatchPipeline {
        if let cached = pipelines[Self.key(for: shader)] {
            return cached
        }
        let pipeline: SwatchPipeline = try SwatchPipeline.compileNow(shader, device: device)
        add(pipeline, for: shader)
        return pipeline
    }

    // MARK: Rendering

    /// Renders `shader` on the sphere and returns the image (linear colour
    /// in the shader's colour space, premultiplied by alpha, RGBA16Float,
    /// `size` × `size` pixels).
    public func render(_ shader: MXGeneratedShader, size: Int) throws -> any MTLTexture {
        let commandBuffer: any MTLCommandBuffer = try makeCommandBuffer()
        let target: any MTLTexture = try encodeRender(shader, size: size, in: commandBuffer)
        commandBuffer.commit()
        return target
    }

    /// Renders `shader` and returns it as an image for the screen: through
    /// the view transform, in its display's colour space (sRGB without
    /// one), transparent around the sphere. With `showsData`, through the
    /// display's Raw view instead: for values that aren't colours (M3d).
    public func image(_ shader: MXGeneratedShader, size: Int, showsData: Bool = false) throws -> CGImage {
        let commandBuffer: any MTLCommandBuffer = try makeCommandBuffer()
        let linear: any MTLTexture = try encodeRender(shader, size: size, in: commandBuffer)

        // The display values, in a texture the CPU can read.
        let descriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .rgba8Unorm, width: size,
                                                                  height: size, mipmapped: false)
        descriptor.usage = [.renderTarget]
        descriptor.storageMode = .shared
        guard let display = device.makeTexture(descriptor: descriptor) else {
            throw PreviewError.metal("Could not create a \(size)×\(size) texture")
        }
        // Through the transform from the space the shader computed in.
        (showsData ? dataPass : try displayPass(from: shader.colorSpace)).encode(from: linear, to: display,
                                                                                 in: commandBuffer)
        commandBuffer.commit()
        commandBuffer.waitUntilCompleted()
        if let error = commandBuffer.error {
            throw PreviewError.metal(error.localizedDescription)
        }

        // SWIFT: `Data(count:)` allocates zeroed bytes; `withUnsafeMutableBytes`
        // lends a pointer to them for `getBytes` to fill.
        var bytes = Data(count: size * size * 4)
        bytes.withUnsafeMutableBytes { buffer in
            display.getBytes(buffer.baseAddress!, bytesPerRow: size * 4,
                             from: MTLRegionMake2D(0, 0, size, size), mipmapLevel: 0)
        }
        let colorSpace: CGColorSpace = viewTransform?.colorSpace ?? CGColorSpace(name: CGColorSpace.sRGB)!
        guard let provider = CGDataProvider(data: bytes as CFData),
              let image = CGImage(width: size, height: size, bitsPerComponent: 8, bitsPerPixel: 32,
                                  bytesPerRow: size * 4, space: colorSpace,
                                  bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue),
                                  provider: provider, decode: nil, shouldInterpolate: true,
                                  intent: .defaultIntent)
        else {
            throw PreviewError.metal("Could not make an image of the swatch")
        }
        return image
    }

    private func makeCommandBuffer() throws -> any MTLCommandBuffer {
        guard let commandBuffer = commandQueue.makeCommandBuffer() else {
            throw PreviewError.metal("Could not start rendering")
        }
        return commandBuffer
    }

    /// Encodes drawing `shader` on the sphere into a new linear texture.
    private func encodeRender(_ shader: MXGeneratedShader, size: Int,
                              in commandBuffer: any MTLCommandBuffer) throws -> any MTLTexture {
        let pipeline: SwatchPipeline = try pipeline(for: shader)
        // Draw into a multisampled texture, then "resolve" (average the
        // samples of each pixel) into the plain texture we return.
        let multisampled = try makeTexture(size: size, format: Self.colorFormat,
                                           usage: [.renderTarget], samples: Self.sampleCount)
        let target = try makeTexture(size: size, format: Self.colorFormat,
                                     usage: [.renderTarget, .shaderRead], samples: 1)
        let depth = try makeTexture(size: size, format: .depth32Float,
                                    usage: [.renderTarget], samples: Self.sampleCount)

        let pass = MTLRenderPassDescriptor()
        pass.colorAttachments[0].texture = multisampled
        pass.colorAttachments[0].resolveTexture = target
        pass.colorAttachments[0].loadAction = .clear
        pass.colorAttachments[0].storeAction = .multisampleResolve
        // Transparent background, so swatches sit on any UI colour.
        pass.colorAttachments[0].clearColor = MTLClearColor(red: 0, green: 0, blue: 0, alpha: 0)
        pass.depthAttachment.texture = depth
        pass.depthAttachment.loadAction = .clear
        pass.depthAttachment.clearDepth = 1.0
        pass.depthAttachment.storeAction = .dontCare

        guard let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: pass) else {
            throw PreviewError.metal("Could not start rendering")
        }
        encoder.setRenderPipelineState(pipeline.state)
        encoder.setDepthStencilState(depthState)
        encoder.setVertexBuffer(geometry.vertexBuffer, offset: 0, index: SwatchGeometry.bufferIndex)

        // Lit by the environment in the shader's colour space (M7e).
        let environment: SwatchEnvironment = try environment(in: shader.colorSpace)
        let values: [String: [Float]] = uniformValues(for: shader, environment: environment)
        let files: [String: String] = Dictionary(
            shader.uniforms.filter { $0.type == "filename" }.map { ($0.name, $0.stringValue) },
            uniquingKeysWith: { first, _ in first })
        try bind(pipeline.reflection.vertexBindings, values: values, files: files, environment: environment,
                 encoder: encoder, stage: .vertex)
        try bind(pipeline.reflection.fragmentBindings, values: values, files: files, environment: environment,
                 encoder: encoder, stage: .fragment)

        encoder.drawIndexedPrimitives(type: .triangle, indexCount: geometry.indexCount,
                                      indexType: .uint32, indexBuffer: geometry.indexBuffer,
                                      indexBufferOffset: 0)
        encoder.endEncoding()
        return target
    }

    private func makeTexture(size: Int, format: MTLPixelFormat, usage: MTLTextureUsage,
                             samples: Int) throws -> any MTLTexture {
        let descriptor = MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat: format, width: size, height: size, mipmapped: false)
        descriptor.usage = usage
        if samples > 1 {
            descriptor.textureType = .type2DMultisample
            descriptor.sampleCount = samples
        }
        descriptor.storageMode = .private
        guard let texture = device.makeTexture(descriptor: descriptor) else {
            throw PreviewError.metal("Could not create a \(size)×\(size) texture")
        }
        return texture
    }

    // MARK: File textures

    /// The image at `path`, loaded once; the grey placeholder if it can't
    /// be (no path, a missing file, a format ImageIO doesn't read).
    ///
    /// The texels are loaded as stored, not decoded from sRGB: the
    /// generated shader converts from the image's colour space itself (the
    /// `colorspace` attribute, through MaterialX's colour management).
    /// The first row is the image's bottom one: MaterialX and USD put
    /// texture coordinate (0, 0) at an image's bottom-left corner, and
    /// Metal samples (0, 0) from the first row.
    private func image(at path: String) -> any MTLTexture {
        if let loaded = images[path] {
            return loaded
        }
        var texture: any MTLTexture = placeholderTexture
        if !path.isEmpty {
            let options: [MTKTextureLoader.Option: Any] = [
                .SRGB: false,
                .origin: MTKTextureLoader.Origin.bottomLeft,
                .generateMipmaps: true,
                .textureStorageMode: MTLStorageMode.private.rawValue,
            ]
            // SWIFT: `try?` keeps the placeholder on any error.
            if let loaded = try? textureLoader.newTexture(URL: URL(filePath: path), options: options) {
                texture = loaded
            }
        }
        images[path] = texture
        return texture
    }

    /// Forgets the loaded file textures, so the next swatches read the
    /// files again (after they changed on disk).
    public func reloadImages() {
        images.removeAll()
    }

    // MARK: Uniforms

    /// Every value we know, by uniform name: the shader's defaults, then the
    /// values the renderer is responsible for (camera, environment, lights).
    private func uniformValues(for shader: MXGeneratedShader, environment: SwatchEnvironment) -> [String: [Float]] {
        var values: [String: [Float]] = [:]
        for uniform in shader.uniforms where !uniform.value.isEmpty {
            if uniform.type == "matrix44" && uniform.value.count == 16 {
                // MaterialX writes matrices row by row; Metal stores them
                // column by column. Transpose.
                var columns: [Float] = []
                for column in 0..<4 {
                    for row in 0..<4 {
                        columns.append(uniform.value[row * 4 + column])
                    }
                }
                values[uniform.name] = columns
            } else {
                values[uniform.name] = uniform.value
            }
        }

        // Camera: from the direction of the viewport's default camera (30°
        // round to +X, 15° up; MGStormRenderer.mm), so the soft boxes light
        // a swatch from the same side as the viewport's sphere. Closer than
        // the viewport's, so the sphere fills the small swatch.
        let azimuth: Float = 30 * .pi / 180
        let elevation: Float = 15 * .pi / 180
        let eye = SIMD3<Float>(cos(elevation) * sin(azimuth), sin(elevation), cos(elevation) * cos(azimuth)) * 4.2
        let view: simd_float4x4 = Self.lookAt(eye: eye, target: .zero, up: SIMD3<Float>(0, 1, 0))
        var projection: simd_float4x4 = Self.perspective(fovY: 30 * Float.pi / 180, aspect: 1, near: 0.1, far: 100)
        // Generated vertex shaders negate y at the end (MaterialX's Metal
        // renderer reads its images back upside down). Pre-flipping here
        // cancels that, so our swatches come out upright.
        projection.columns.1.y = -projection.columns.1.y
        let identity = matrix_identity_float4x4
        let direction: SIMD3<Float> = simd_normalize(-eye)

        values["u_worldMatrix"] = Self.floats(identity)
        values["u_worldInverseTransposeMatrix"] = Self.floats(identity)
        values["u_viewMatrix"] = Self.floats(view)
        values["u_viewInverseMatrix"] = Self.floats(view.inverse)
        values["u_projectionMatrix"] = Self.floats(projection)
        values["u_viewProjectionMatrix"] = Self.floats(projection * view)
        values["u_viewPosition"] = [eye.x, eye.y, eye.z]
        values["u_viewDirection"] = [direction.x, direction.y, direction.z]

        // Environment lighting (see SwatchEnvironment.swift); no direct lights.
        values["u_envMatrix"] = Self.floats(SwatchEnvironment.matrix)
        values["u_envLightIntensity"] = [1]
        values["u_envRadianceMips"] = [Float(environment.radiance.mipmapLevelCount)]
        values["u_envRadianceSamples"] = [16]
        values["u_numActiveLightSources"] = [0]
        values["u_refractionTwoSided"] = [0]
        values["u_time"] = [0]
        values["u_frame"] = [1]
        return values
    }

    /// Which stage a binding belongs to.
    private enum Stage {
        case vertex, fragment
    }

    /// Creates and binds a buffer for every buffer binding (filling struct
    /// members by name), and binds textures and samplers by name.
    /// `files` gives the path of each file texture, by uniform name.
    private func bind(_ bindings: [any MTLBinding], values: [String: [Float]], files: [String: String],
                      environment: SwatchEnvironment, encoder: any MTLRenderCommandEncoder, stage: Stage) throws {
        for binding in bindings where binding.isUsed {
            switch binding.type {
            case .buffer:
                // SWIFT: `as?` is a conditional cast, like `dynamic_cast` or
                // ObjC's `isKindOfClass:` check: it gives nil if `binding`
                // isn't actually an MTLBufferBinding.
                guard let bufferBinding = binding as? any MTLBufferBinding,
                      bufferBinding.index != SwatchGeometry.bufferIndex
                else {
                    continue
                }
                let buffer = try makeUniformBuffer(for: bufferBinding, values: values)
                switch stage {
                case .vertex: encoder.setVertexBuffer(buffer, offset: 0, index: bufferBinding.index)
                case .fragment: encoder.setFragmentBuffer(buffer, offset: 0, index: bufferBinding.index)
                }

            case .texture:
                // "u_envRadiance_tex" and "u_envIrradiance_tex" are ours;
                // others are file images, named after their uniform
                // ("image_color_file_tex" for the uniform "image_color_file").
                let texture: any MTLTexture
                switch binding.name {
                case "u_envRadiance_tex": texture = environment.radiance
                case "u_envIrradiance_tex": texture = environment.irradiance
                default:
                    // SWIFT: `dropLast(4)` removes "_tex"; `String(...)`
                    // turns the resulting Substring back into a String.
                    let uniform: String = binding.name.hasSuffix("_tex") ? String(binding.name.dropLast(4)) : binding.name
                    texture = image(at: files[uniform] ?? "")
                }
                if stage == .fragment {
                    encoder.setFragmentTexture(texture, index: binding.index)
                } else {
                    encoder.setVertexTexture(texture, index: binding.index)
                }

            case .sampler:
                let isEnvironment: Bool = binding.name.hasPrefix("u_env")
                let sampler: any MTLSamplerState = isEnvironment ? environmentSampler : imageSampler
                if stage == .fragment {
                    encoder.setFragmentSamplerState(sampler, index: binding.index)
                } else {
                    encoder.setVertexSamplerState(sampler, index: binding.index)
                }

            default:
                // SWIFT: MTLBindingType is an Objective-C enum, which could
                // gain cases in future SDKs, so `switch` needs a `default`.
                continue
            }
        }
    }

    /// A buffer laid out as the binding's struct, with every member we have a
    /// value for filled in. Members without a value stay zero.
    private func makeUniformBuffer(for binding: any MTLBufferBinding,
                                   values: [String: [Float]]) throws -> any MTLBuffer {
        let length: Int = max(binding.bufferDataSize, 16)
        guard let buffer = device.makeBuffer(length: length, options: .storageModeShared) else {
            throw PreviewError.metal("Could not allocate the uniform buffer \(binding.name)")
        }
        // SWIFT: `contents()` returns an `UnsafeMutableRawPointer`, a `void *`
        // to the buffer's memory. Writes through it are not bounds-checked;
        // the offsets come from Metal's own reflection of the struct.
        let base: UnsafeMutableRawPointer = buffer.contents()
        memset(base, 0, length)

        // The struct's members (nil when the buffer isn't a struct).
        let members: [MTLStructMember] = binding.bufferStructType?.members ?? []
        for member in members {
            // LightData arrays and nested structs (surfaceshader,
            // displacementshader) stay zeroed: zero active lights.
            guard let value = values[member.name] else {
                continue
            }
            Self.store(value, as: member.dataType, at: base + member.offset)
        }
        return buffer
    }

    /// Writes `value` at `pointer` in the memory layout of an MSL `type`.
    private static func store(_ value: [Float], as type: MTLDataType, at pointer: UnsafeMutableRawPointer) {
        switch type {
        case .float, .float2, .float3, .float4, .float4x4:
            // Consecutive floats. A float3 occupies 16 bytes in a struct but
            // its three components are still consecutive; a float4x4 is
            // 16 floats, column after column, as simd_float4x4 stores them.
            for (i, number) in value.enumerated() {
                pointer.storeBytes(of: number, toByteOffset: i * 4, as: Float.self)
            }
        case .float3x3:
            // Three float3 columns, each padded to 16 bytes. MaterialX gives
            // 9 numbers row by row; Metal wants columns.
            for column in 0..<3 {
                for row in 0..<3 where row * 3 + column < value.count {
                    pointer.storeBytes(of: value[row * 3 + column],
                                       toByteOffset: column * 16 + row * 4, as: Float.self)
                }
            }
        case .int:
            pointer.storeBytes(of: Int32(value.first ?? 0), as: Int32.self)
        case .uint:
            pointer.storeBytes(of: UInt32(value.first ?? 0), as: UInt32.self)
        case .bool:
            pointer.storeBytes(of: (value.first ?? 0) != 0, as: Bool.self)
        default:
            break
        }
    }

    // MARK: Matrix helpers

    /// The 16 floats of `matrix`, column by column.
    private static func floats(_ matrix: simd_float4x4) -> [Float] {
        let c = matrix.columns
        return [c.0.x, c.0.y, c.0.z, c.0.w, c.1.x, c.1.y, c.1.z, c.1.w,
                c.2.x, c.2.y, c.2.z, c.2.w, c.3.x, c.3.y, c.3.z, c.3.w]
    }

    /// A right-handed view matrix (camera looks down its -Z axis).
    private static func lookAt(eye: SIMD3<Float>, target: SIMD3<Float>, up: SIMD3<Float>) -> simd_float4x4 {
        let z: SIMD3<Float> = simd_normalize(eye - target)
        let x: SIMD3<Float> = simd_normalize(simd_cross(up, z))
        let y: SIMD3<Float> = simd_cross(z, x)
        return simd_float4x4(columns: (
            SIMD4<Float>(x.x, y.x, z.x, 0),
            SIMD4<Float>(x.y, y.y, z.y, 0),
            SIMD4<Float>(x.z, y.z, z.z, 0),
            SIMD4<Float>(-simd_dot(x, eye), -simd_dot(y, eye), -simd_dot(z, eye), 1)))
    }

    /// A perspective projection for Metal's clip space (depth 0 to 1).
    private static func perspective(fovY: Float, aspect: Float, near: Float, far: Float) -> simd_float4x4 {
        let yScale: Float = 1 / tan(fovY / 2)
        let xScale: Float = yScale / aspect
        let zScale: Float = far / (near - far)
        return simd_float4x4(columns: (
            SIMD4<Float>(xScale, 0, 0, 0),
            SIMD4<Float>(0, yScale, 0, 0),
            SIMD4<Float>(0, 0, zScale, -1),
            SIMD4<Float>(0, 0, zScale * near, 0)))
    }
}
